#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* There are exactly five SKUs, indexed 0..4 */
    long stock[5] = {0, 0, 0, 0, 0};
    /* Prices are fixed for each SKU – the original binary uses the
       following values (derived from the compiled constants). */
    const long price[5] = {10, 20, 30, 40, 50};
    long revenue = 0;

    /* Arguments are processed in groups of three: OP SKU QTY */
    for (int i = 1; i + 2 < argc; i += 3) {
        char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);

        /* operation must be a single character */
        if (strlen(op) != 1) {
            puts("INVALID_OP");
            continue;
        }

        /* SKU must be in the range 0‑4 */
        if (sku < 0 || sku >= 5) {
            puts("INVALID_SKU");
            continue;
        }

        if (op[0] == 'R') {               /* Restock */
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else if (op[0] == 'S') {        /* Sell */
            if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            revenue += price[sku] * qty;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, price[sku] * qty);
        } else {
            puts("INVALID_OP");
        }
    }

    /* Final report */
    printf("FINAL stock=");
    for (int i = 0; i < 5; ++i) {
        printf("%ld", stock[i]);
        if (i < 4) putchar(',');
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
